(66, "التحريم", "At-Tahrim",
 [(6,"ماذا يأمرنا الله تجاه أنفسنا وأهلينا؟","What does Allah command about ourselves and our families?","أن نحمي أنفسنا وأهلنا من النار بطاعة الله.","To protect ourselves and our families from the Fire by obeying Allah."),
  (8,"ما هي «التوبة النصوح»؟","What is «توبة نصوحا» (sincere repentance)?","توبة صادقة: نترك الذنب، ونندم، ولا نعود إليه.","A sincere repentance: leave the sin, regret it, and never return to it."),
  (10,"ماذا نتعلم من امرأتي نوح ولوط؟","What do we learn from the wives of Nuh and Lut?","لم ينفعهما قربهما من نبيين لأنهما لم تؤمنا، فكل إنسان مسؤول عن نفسه.","Being close to prophets didn't help them since they didn't believe — each person is responsible for himself."),
  (11,"بماذا دعت امرأة فرعون؟","What did Pharaoh's wife pray for?","دعت الله أن يبني لها بيتًا في الجنة وينجيها من فرعون.","She asked Allah for a house in Paradise and to save her from Pharaoh."),
  (12,"من هي مريم ابنة عمران؟","Who is Maryam, daughter of 'Imran?","امرأة صالحة صدّقت بكلمات ربها وكانت من القانتين.","A righteous woman who believed her Lord's words and was devoutly obedient.")],
 [("🏠","نساعد أهلنا على طاعة الله.","We help our families obey Allah."),("🔄","نتوب توبة صادقة.","We repent sincerely."),("🏡","امرأة فرعون قدوة في الإيمان.","Pharaoh's wife is a model of faith."),("🌸","مريم قدوة في الطاعة.","Maryam is a model of obedience.")],
 (10,12), [6,7,12],
 [("مِمَّ نحمي أنفسنا وأهلنا؟","From what do we protect ourselves and families?",[("من النار","The Fire"),("من المطر","The rain"),("من الشمس","The sun")],0),
  ("التوبة النصوح هي:","Sincere repentance is:",[("ترك الذنب والندم وعدم العودة","Leaving sin, regret and not returning"),("الاعتذار بلا تغيير","Apologizing without changing"),("تأجيل التوبة","Delaying repentance")],0),
  ("ماذا طلبت امرأة فرعون؟","What did Pharaoh's wife ask for?",[("بيتًا في الجنة","A house in Paradise"),("قصرًا في الدنيا","A palace in this world"),("ذهبًا","Gold")],0),
  ("من التي ذُكرت في آخر السورة؟","Who is mentioned at the end of the surah?",[("مريم ابنة عمران","Maryam, daughter of 'Imran"),("هاجر","Hajar"),("بلقيس","Bilqis")],0)]),
